// Bundled copy of supabase/content/waste_content.json (generated by
// supabase/scripts/build_seed.py). Gives the scanner item names, bins and instructions
// instantly and offline; Supabase (Phase 13+) stays the editable source of truth.
import raw from "@/content/waste_content.json";
import type { Category } from "@/lib/detector/types";

interface RawItem {
  class_key: string;
  display_name: string;
  display_name_fil?: string | null;
  category: string;
  detectable: boolean;
  short_instruction: string;
  reuse_tip?: string | null;
  prep_steps?: { title: string; detail: string }[];
  why_text?: string | null;
  contamination_note?: string | null;
  aliases?: string[];
}

export interface ItemContent {
  classKey: string;
  name: string;
  nameFil?: string;
  category: Category;
  detectable: boolean;
  instruction: string;
  reuseTip?: string;
  steps: { title: string; detail: string }[];
  why?: string;
  contaminationNote?: string;
  aliases: string[];
}

function toItem(i: RawItem): ItemContent {
  return {
    classKey: i.class_key,
    name: i.display_name,
    nameFil: i.display_name_fil ?? undefined,
    category: i.category as Category,
    detectable: i.detectable,
    instruction: i.short_instruction,
    reuseTip: i.reuse_tip ?? undefined,
    steps: i.prep_steps ?? [],
    why: i.why_text ?? undefined,
    contaminationNote: i.contamination_note ?? undefined,
    aliases: i.aliases ?? [],
  };
}

export const ITEMS: ItemContent[] = (raw.items as RawItem[]).map(toItem);
const BY_KEY = new Map(ITEMS.map((i) => [i.classKey, i]));

export function getItem(classKey: string): ItemContent | undefined {
  return BY_KEY.get(classKey);
}

export const DETECTABLE_KEYS = ITEMS.filter((i) => i.detectable).map((i) => i.classKey);
